12	// This file guards a paginated, time-windowed QueryTxs against the reorg shape
13	// that is easiest to miss: the chain keeps the SAME height span, the SAME block
14	// hashes, the SAME parent links and the SAME ordered transaction lists at
15	// every height — only the timestamps of SOME blocks move. The pinned upper
16	// height therefore does not change and no hash appears or vanishes; the only
17	// thing that changes is which occurrences survive the half-open timestamp
18	// window. A page still has to describe ONE complete main chain: its hit
19	// records, TotalMatches, MatchedBlocks, the pinned upper height and the
20	// continuation cursor must all be old-chain or all new-chain, never hits read
21	// under the old times with statistics counted under the new times.
22	//
23	// The window is [0, 110): start included, end excluded. Starting the window at
24	// zero is deliberate: h1's real timestamp of zero sits exactly at the included
25	// start and must stay matched both before and after the reorg, while h4's
26	// missing timestamp is rejected, so the "zero is a value, nil is absent"
27	// distinction survives the reorg instead of being asserted only on static
28	// chains. Timestamps are deliberately non-monotonic in height (110 appears
29	// below 105), so the window can never be mistaken for a height range.
30	//
31	//	                    old time   new time   in window old -> new
32	//	h1 parent g  [m, x]    0          0        yes -> yes   (real zero at the included start, unchanged)
33	//	h2 parent h1 [m, m]   105        120       yes -> OUT   (both occurrences leave together)
34	//	h3 parent h2 [m, z]   110        100       OUT -> in    (excluded end becomes included)
35	//	h4 parent h3 [m, q]    nil       105       OUT -> in    (missing stays excluded, a value enters)
36	//	h5 parent h4 [m, m]   108        102       yes -> yes   (stays, times still differ)
37	//
38	// Filter "m", window [0,110), ascending, page size 2.
39	//
40	// Old answer (range 1..5): h1 m@0, h2 m@0, h2 m@1, h5 m@0, h5 m@1 = 5
41	// occurrences over 3 matched blocks (h1, h2, h5), upper height 5.
42	// New answer (range 1..5): h1 m@0, h3 m@0, h4 m@0, h5 m@0, h5 m@1 = 5
43	// occurrences over 4 matched blocks (h1, h3, h4, h5), upper height 5.
44	//
45	// The totals are deliberately equal (5) while every other observable differs:
46	// the two complete answers share only the h1 and h5 records. A torn page whose
47	// hits come from the old times but whose MatchedBlocks came from the new times
48	// (or the reverse) is exposed even though TotalMatches alone would look fine.
49	
50	const (
51		twShiftWindowStart = int64(0)
52		twShiftWindowEnd   = int64(110)
53		twShiftPageSize    = 2
54	)
55	
56	func twShiftBlock(height int64, hash, parent string, txs []string, time *int64) Block {
57		return Block{Height: height, Hash: hash, Parent: parent, Txs: txs, Time: time}
58	}
59	
60	// twShiftOldChain is the main chain before the time-only reorg.
61	func twShiftOldChain() []Block {
62		return []Block{
63			twShiftBlock(1, "h1", "g", []string{"m", "x"}, intptr(0)),
64			twShiftBlock(2, "h2", "h1", []string{"m", "m"}, intptr(105)),
65			twShiftBlock(3, "h3", "h2", []string{"m", "z"}, intptr(110)),
66			twShiftBlock(4, "h4", "h3", []string{"m", "q"}, nil),
67			twShiftBlock(5, "h5", "h4", []string{"m", "m"}, intptr(108)),
68		}
69	}
70	
71	// twShiftBranch is the alternate branch handed to Reorg. It starts at height 2
72	// rooted at the retained h1 and keeps every hash, parent link and transaction
73	// list; only timestamps move (h2 105->120, h3 110->100, h4 nil->105,
74	// h5 108->102), while h1 at zero is left untouched.
75	func twShiftBranch() []Block {
76		return []Block{
77			twShiftBlock(2, "h2", "h1", []string{"m", "m"}, intptr(120)),
78			twShiftBlock(3, "h3", "h2", []string{"m", "z"}, intptr(100)),
79			twShiftBlock(4, "h4", "h3", []string{"m", "q"}, intptr(105)),
80			twShiftBlock(5, "h5", "h4", []string{"m", "m"}, intptr(102)),
81		}
82	}
83	
84	// twShiftNewChain is the complete main chain after the reorg: retained h1 plus
85	// the re-timed branch.
86	func twShiftNewChain() []Block {
87		chain := append([]Block{}, twShiftOldChain()[:1]...)
88		return append(chain, twShiftBranch()...)
89	}
90	
91	func buildTwShiftOldChain(t *testing.T) *Index {
92		t.Helper()
93		index := New()
94		for _, b := range twShiftOldChain() {
95			if err := index.Append(b); err != nil {
96				t.Fatalf("setup append at %d: %v", b.Height, err)
97			}
98		}
99		return index
100	}
101	
102	func twShiftQuery() TxQuery {
103		return TxQuery{
104			TxIDs:     []string{"m"},
105			TimeStart: intptr(twShiftWindowStart),
106			TimeEnd:   intptr(twShiftWindowEnd),
107			PageSize:  twShiftPageSize,
108		}
109	}
110	
111	// twReferenceHits is an independent oracle: it walks an explicit chain by
112	// increasing height and in-block position, keeping an occurrence only when its
113	// identifier passes the set filter AND its block timestamp lies in the
114	// half-open window. Ordering is derived from height/position alone, never from
115	// the timestamps, which are non-monotonic in this fixture. It does not use the
116	// Index under test, so a shared QueryTxs bug cannot make an expectation match
117	// itself.
118	func twReferenceHits(chain []Block, txIDs []string, start, end int64) []TxHit {
119		want := map[string]bool{}
120		for _, id := range txIDs {
121			want[id] = true
122		}
123		inWindow := func(when *int64) bool {
124			if when == nil {
125				return false // a missing timestamp never matches
126			}
127			return *when >= start && *when < end // start included, end excluded
128		}
129		hits := []TxHit{}
130		for _, block := range chain {
131			if !inWindow(block.Time) {
132				continue
133			}
134			for position, tx := range block.Txs {
135				if want[tx] {
136					hits = append(hits, TxHit{
137						Height:    block.Height,
138						BlockHash: block.Hash,
139						TxID:      tx,
140						Position:  position,
141					})
142				}
143			}
144		}
145		return hits
146	}
147	
148	func twReferenceMatchedBlocks(chain []Block, txIDs []string, start, end int64) int64 {
149		want := map[string]bool{}
150		for _, id := range txIDs {
151			want[id] = true
152		}
153		var blocks int64
154		for _, block := range chain {
155			if block.Time == nil || *block.Time < start || *block.Time >= end {
156				continue
157			}
158			for _, tx := range block.Txs {
159				if want[tx] {
160					blocks++ // a block counts once however many matches it holds
161					break
162				}
163			}
164		}
165		return blocks
166	}
167	
168	// twReferencePage slices one page at the given offset of the oracle's complete
169	// filtered occurrence list and attaches the statistics over the WHOLE pinned
170	// range. The cursor stays opaque; tests validate it by following it.
171	func twReferencePage(chain []Block, pageSize int, offset int64) TxPage {
172		full := twReferenceHits(chain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
173		rest := full[offset:]
174		n := pageSize
175		if n > len(rest) {
176			n = len(rest)
177		}
178		return TxPage{
179			Hits:          append([]TxHit{}, rest[:n]...),
180			TotalMatches:  int64(len(full)),
181			MatchedBlocks: twReferenceMatchedBlocks(chain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd),
182			ToHeight:      chain[len(chain)-1].Height,
183		}
184	}
185	
186	// Hand-derived first pages; the guarantee rests on these literal records and
187	// counts, not on oracle-vs-DeepEqual alone.
188	func literalTwShiftOldFirstPage() TxPage {
189		return TxPage{
190			Hits: []TxHit{
191				{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
192				{Height: 2, BlockHash: "h2", TxID: "m", Position: 0},
193			},
194			TotalMatches:  5,
195			MatchedBlocks: 3,
196			ToHeight:      5,
197		}
198	}
199	
200	func literalTwShiftNewFirstPage() TxPage {
201		return TxPage{
202			Hits: []TxHit{
203				{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
204				{Height: 3, BlockHash: "h3", TxID: "m", Position: 0},
205			},
206			TotalMatches:  5,
207			MatchedBlocks: 4,
208			ToHeight:      5,
209		}
210	}
211	
212	// The structural invariant the whole regression rests on: above the retained
213	// h1, the reorg changes timestamps only. Every height, hash, parent link and
214	// ordered transaction list is identical on the two chains, the tip stays 5,
215	// and at least one block actually moves across each window boundary.
216	func TestReorgTimeWindowFixtureKeepsStructureMovesTimesOnly(t *testing.T) {
217		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
218		if len(oldChain) != len(newChain) || len(oldChain) != 5 {
219			t.Fatalf("chain lengths old=%d new=%d, want 5/5", len(oldChain), len(newChain))
220		}
221		for i := range oldChain {
222			o, n := oldChain[i], newChain[i]
223			if o.Height != n.Height || o.Hash != n.Hash || o.Parent != n.Parent {
224				t.Fatalf("height %d identity changed: old={%d %s %s} new={%d %s %s}",
225					i+1, o.Height, o.Hash, o.Parent, n.Height, n.Hash, n.Parent)
226			}
227			if !reflect.DeepEqual(o.Txs, n.Txs) {
228				t.Fatalf("height %d transaction list changed: old=%v new=%v", o.Height, o.Txs, n.Txs)
229			}
230		}
231		// Per-height transition table, including the unchanged real-zero h1 and the
232		// missing->known h4.
233		flips := map[int64]struct {
234			oldIn, newIn bool
235			oldTime      *int64
236			newTime      *int64
237		}{
238			1: {true, true, intptr(0), intptr(0)},
239			2: {true, false, intptr(105), intptr(120)},
240			3: {false, true, intptr(110), intptr(100)},
241			4: {false, true, nil, intptr(105)},
242			5: {true, true, intptr(108), intptr(102)},
243		}
244		movedOut, movedIn := 0, 0
245		for height, want := range flips {
246			o, n := oldChain[height-1].Time, newChain[height-1].Time
247			if !sameIntptr(o, want.oldTime) || !sameIntptr(n, want.newTime) {
248				t.Fatalf("height %d times old=%v new=%v, want %v/%v", height, o, n, want.oldTime, want.newTime)
249			}
250			gotOld := timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}.contains(o)
251			gotNew := timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}.contains(n)
252			if gotOld != want.oldIn || gotNew != want.newIn {
253				t.Fatalf("height %d window membership old=%v(want %v) new=%v(want %v)",
254					height, gotOld, want.oldIn, gotNew, want.newIn)
255			}
256			if want.oldIn && !want.newIn {
257				movedOut++
258			}
259			if !want.oldIn && want.newIn {
260				movedIn++
261			}
262		}
263		if movedOut != 1 || movedIn != 2 {
264			t.Fatalf("boundary crossings: movedOut=%d movedIn=%d, want 1/2", movedOut, movedIn)
265		}
266	
267		// A live Reorg of this shape must report exactly the re-timed heights
268		// (h1's time is unchanged and is not reported), keep the tip at 5, and
269		// leave every hash/parent/tx list in place.
270		index := buildTwShiftOldChain(t)
271		dropped, err := index.Reorg(twShiftBranch())
272		if err != nil {
273			t.Fatalf("time-only reorg refused: %v", err)
274		}
275		if want := []int64{2, 3, 4, 5}; !reflect.DeepEqual(dropped, want) {
276			t.Fatalf("dropped=%v, want the four re-timed heights %v", dropped, want)
277		}
278		if index.Tip != 5 {
279			t.Fatalf("tip=%d, want unchanged 5", index.Tip)
280		}
281		for _, want := range newChain {
282			got, ok := index.Blocks[want.Height]
283			if !ok {
284				t.Fatalf("height %d missing after reorg", want.Height)
285			}
286			if !sameBlock(got, want) {
287				t.Fatalf("height %d stored block=%+v, want %+v", want.Height, got, want)
288			}
289			if index.ByHash[want.Hash] != want.Height {
290				t.Fatalf("hash %q resolves to %d, want %d", want.Hash, index.ByHash[want.Hash], want.Height)
291			}
292		}
293	}
