305	func TestReorgTimeWindowQueryFixtureSemanticsOnBothChains(t *testing.T) {
306		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
307	
308		oldHits := twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
309		newHits := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
310		wantOld := []TxHit{
311			{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
312			{Height: 2, BlockHash: "h2", TxID: "m", Position: 0},
313			{Height: 2, BlockHash: "h2", TxID: "m", Position: 1},
314			{Height: 5, BlockHash: "h5", TxID: "m", Position: 0},
315			{Height: 5, BlockHash: "h5", TxID: "m", Position: 1},
316		}
317		wantNew := []TxHit{
318			{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
319			{Height: 3, BlockHash: "h3", TxID: "m", Position: 0},
320			{Height: 4, BlockHash: "h4", TxID: "m", Position: 0},
321			{Height: 5, BlockHash: "h5", TxID: "m", Position: 0},
322			{Height: 5, BlockHash: "h5", TxID: "m", Position: 1},
323		}
324		if !reflect.DeepEqual(oldHits, wantOld) {
325			t.Fatalf("old oracle hits=%v, want %v", oldHits, wantOld)
326		}
327		if !reflect.DeepEqual(newHits, wantNew) {
328			t.Fatalf("new oracle hits=%v, want %v", newHits, wantNew)
329		}
330		// Both chains hold five occurrences, but over a different number of blocks:
331		// this count divergence is what a same-total torn page cannot paper over.
332		if twReferenceMatchedBlocks(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd) != 3 {
333			t.Fatal("old chain must match 3 blocks (h1, h2, h5)")
334		}
335		if twReferenceMatchedBlocks(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd) != 4 {
336			t.Fatal("new chain must match 4 blocks (h1, h3, h4, h5)")
337		}
338		// Repeated identifiers inside one block keep their own positions and count
339		// separately; the non-matching companions x, z, q never leak through.
340		for _, gone := range []TxHit{
341			{Height: 2, BlockHash: "h2", TxID: "m", Position: 0},
342			{Height: 2, BlockHash: "h2", TxID: "m", Position: 1},
343		} {
344			if containsHit(newHits, gone) {
345				t.Fatalf("old-time occurrence %+v must leave the window", gone)
346			}
347		}
348		for _, entered := range []TxHit{
349			{Height: 3, BlockHash: "h3", TxID: "m", Position: 0},
350			{Height: 4, BlockHash: "h4", TxID: "m", Position: 0},
351		} {
352			if !containsHit(newHits, entered) {
353				t.Fatalf("new-time occurrence %+v must enter the window: %v", entered, newHits)
354			}
355		}
356		// Timestamps are not monotonic with height (h3 at 110 sits below h2 at
357		// 105/120, h5 dips to 102 after h4's 105), yet both answers stay in
358		// height/position order — never timestamp order.
359		requireOrdered(t, oldHits)
360		requireOrdered(t, newHits)
361	
362		// The oracle must match the live index on both complete chain states.
363		index := buildTwShiftOldChain(t)
364		live, err := index.QueryTxs(twShiftQuery())
365		if err != nil {
366			t.Fatal(err)
367		}
368		if !reflect.DeepEqual(viewOf(live), viewOf(twReferencePage(oldChain, twShiftPageSize, 0))) {
369			t.Fatalf("live old-chain page=%+v", live)
370		}
371		if !reflect.DeepEqual(live.Hits, literalTwShiftOldFirstPage().Hits) {
