373		}
374	
375		if _, err := index.Reorg(twShiftBranch()); err != nil {
376			t.Fatalf("time-only reorg refused: %v", err)
377		}
378		live, err = index.QueryTxs(twShiftQuery())
379		if err != nil {
380			t.Fatal(err)
381		}
382		if !reflect.DeepEqual(viewOf(live), viewOf(twReferencePage(newChain, twShiftPageSize, 0))) {
383			t.Fatalf("live new-chain page=%+v", live)
384		}
385		if !reflect.DeepEqual(live.Hits, literalTwShiftNewFirstPage().Hits) {
386			t.Fatalf("live new first page hits=%v, want literal %v", live.Hits, literalTwShiftNewFirstPage().Hits)
387		}
