389		// On the OLD chain, starting the window exactly at zero still rejects the
390		// missing timestamp: widening the end to 200 admits every block carrying a
391		// value (including the real-zero h1 and the 110 h3) but never the nil h4.
392		oldIndex := buildTwShiftOldChain(t)
393		wide, err := oldIndex.QueryTxs(TxQuery{
394			TxIDs: []string{"m"}, TimeStart: intptr(0), TimeEnd: intptr(200),
395		})
396		if err != nil {
397			t.Fatal(err)
398		}
