401			wideHeights[h.Height] = true
402		}
403		if !reflect.DeepEqual(wideHeights, map[int64]bool{1: true, 2: true, 3: true, 5: true}) {
404			t.Fatalf("old chain [0,200) matched heights %v, want every valued block 1,2,3,5 and not the nil h4", wideHeights)
