410		// The half-open boundary and the real-zero/missing distinction are pinned
411		// on the new chain as well: the included zero keeps h1, a positive start
412		// drops it, h3 at 100 is included by [100,101), and h4's 105 is the
413		// excluded end of [0,105).
414		for _, tc := range []struct {
415			name        string
416			start, end  int64
417			wantHeights []int64
418		}{
419			{"fixture window [0,110)", 0, 110, []int64{1, 3, 4, 5}},
420			{"positive start drops real zero", 1, 110, []int64{3, 4, 5}},
421			{"end excluded at 105", 0, 105, []int64{1, 3, 5}},
422			{"only the included 100", 100, 101, []int64{3}},
423			{"window around zero keeps just h1", 0, 1, []int64{1}},
424		} {
425			t.Run(tc.name, func(t *testing.T) {
426				page, err := index.QueryTxs(TxQuery{
