448	// classifyTimeWindowTxPage accepts got only when its visible contents are the
449	// first-page view of exactly one chain state under the pinned window. The
450	// opaque cursor is excluded and validated separately by following it. Records
451	// are provenanced against the COMPLETE filtered occurrence lists, so a page
452	// that stitches old-time hits to new-time statistics is rejected as MIXED even
453	// though both chains report TotalMatches 5 and the same upper height 5.
454	func classifyTimeWindowTxPage(got, oldRef, newRef TxPage, oldAllHits, newAllHits []TxHit) error {
455		type view struct {
456			Hits          []TxHit
457			TotalMatches  int64
458			MatchedBlocks int64
459			ToHeight      int64
460		}
461		of := func(p TxPage) view {
462			return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
463		}
464		g, o, n := of(got), of(oldRef), of(newRef)
465		if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
466			return nil
467		}
468	
469		var report strings.Builder
470		fmt.Fprintln(&report, "time-windowed QueryTxs page does not match one complete main chain:")
471		tags := map[string]bool{}
472		tag := func(name string, gotV, oldV, newV any) {
473			matchesOld := reflect.DeepEqual(gotV, oldV)
474			matchesNew := reflect.DeepEqual(gotV, newV)
475			label := "neither"
476			switch {
477			case matchesOld && matchesNew:
478				label = "both"
479			case matchesOld:
480				label = "OLD"
481				tags["old"] = true
482			case matchesNew:
483				label = "NEW"
484				tags["new"] = true
485			}
486			fmt.Fprintf(&report, "  %-15s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
487		}
488		tag("ToHeight", g.ToHeight, o.ToHeight, n.ToHeight)
489		tag("TotalMatches", g.TotalMatches, o.TotalMatches, n.TotalMatches)
490		tag("MatchedBlocks", g.MatchedBlocks, o.MatchedBlocks, n.MatchedBlocks)
491	
492		oldByKey, newByKey := map[TxHit]bool{}, map[TxHit]bool{}
493		for _, h := range oldAllHits {
494			oldByKey[h] = true
495		}
496		for _, h := range newAllHits {
497			newByKey[h] = true
498		}
499		var inOld, inNew, inNeither, onlyOld, onlyNew int
500		ordered := true
501		for i, h := range g.Hits {
502			co, cn := oldByKey[h], newByKey[h]
503			if co {
504				inOld++
505			}
506			if cn {
507				inNew++
508			}
509			if co && !cn {
510				onlyOld++
511			}
512			if cn && !co {
513				onlyNew++
514			}
515			if !co && !cn {
516				inNeither++
517			}
518			if i > 0 {
519				prev := g.Hits[i-1]
520				if h.Height < prev.Height || (h.Height == prev.Height && h.Position <= prev.Position) {
521					ordered = false
522				}
523			}
524			if h.Height > g.ToHeight {
525				fmt.Fprintf(&report, "  hit above pinned ToHeight %d: %+v\n", g.ToHeight, h)
526			}
527		}
528		fmt.Fprintf(&report, "  Hits provenance  on-old=%d on-new=%d only-old=%d only-new=%d on-neither=%d (ordered=%v)\n",
529			inOld, inNew, onlyOld, onlyNew, inNeither, ordered)
530		if onlyOld > 0 {
531			tags["old"] = true
532		}
533		if onlyNew > 0 {
534			tags["new"] = true
535		}
536		switch {
537		case tags["old"] && tags["new"]:
538			fmt.Fprintf(&report, "  => MIXED: records and statistics come from different timestamp states; one page must reflect a single main chain")
539		case inNeither > 0:
540			fmt.Fprintf(&report, "  => CORRUPT: records exist under neither timestamp state")
541		case !ordered:
542			fmt.Fprintf(&report, "  => CORRUPT: page is not in height/position order")
543		default:
544			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new timestamp state")
545		}
546		return errors.New(report.String())
547	}
