549	// The classifier must accept both complete answers and reject the
550	// equal-total mixtures this reorg shape is prone to.
551	func TestClassifyTimeWindowTxPageRejectsStitchedPages(t *testing.T) {
552		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
553		oldRef := twReferencePage(oldChain, twShiftPageSize, 0)
554		newRef := twReferencePage(newChain, twShiftPageSize, 0)
555		oldAll := twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
556		newAll := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
557		classify := func(page TxPage) error { return classifyTimeWindowTxPage(page, oldRef, newRef, oldAll, newAll) }
558		if err := classify(oldRef); err != nil {
559			t.Fatalf("pure old page rejected: %v", err)
560		}
561		if err := classify(newRef); err != nil {
562			t.Fatalf("pure new page rejected: %v", err)
563		}
564	
565		// Mixture 1: old-time records, but new-time MatchedBlocks. TotalMatches is
566		// 5 on both chains, so a total-only consistency check would accept this.
567		mixed1 := oldRef
568		mixed1.MatchedBlocks = newRef.MatchedBlocks
569		if err := classify(mixed1); err == nil {
570			t.Fatal("old hits with new-time block count were accepted")
571		} else if !strings.Contains(err.Error(), "MIXED") {
572			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
573		}
574	
575		// Mixture 2: the exact torn answer the task names — records read under the
576		// old times, statistics counted under the new times — built by hand rather
577		// than borrowed from either reference page.
578		mixed2 := TxPage{
579			Hits: []TxHit{
580				{Height: 1, BlockHash: "h1", TxID: "m", Position: 0}, // shared
581				{Height: 2, BlockHash: "h2", TxID: "m", Position: 0}, // OLD only
582			},
583			TotalMatches:  5,
584			MatchedBlocks: 4, // NEW
585			ToHeight:      5,
586		}
587		if err := classify(mixed2); err == nil {
588			t.Fatal("stitched old-records/new-stats page was accepted")
589		} else if !strings.Contains(err.Error(), "MIXED") {
590			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
591		}
592	
593		// Mixture 3: new-time records carrying the old block count.
594		mixed3 := newRef
595		mixed3.MatchedBlocks = oldRef.MatchedBlocks
596		if err := classify(mixed3); err == nil {
597			t.Fatal("new hits with old-time block count were accepted")
598		} else if !strings.Contains(err.Error(), "MIXED") {
599			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
600		}
601	
602		// Corruption: a matched-block count that belongs to neither state.
603		corrupt := newRef
604		corrupt.MatchedBlocks = 99
605		if err := classify(corrupt); err == nil {
606			t.Fatal("corrupt stats matching neither state were accepted")
607		}
608	}
