610	// Ordering 1: the windowed first page is holding the lock on the complete OLD
611	// timestamp state (tip already pinned) when the time-only reorg starts and
612	// blocks on the lock. The page must finish entirely against the old times —
613	// literal h1/h2 records, 5 occurrences over 3 blocks, upper height 5 and a
614	// cursor pinned to the old fingerprint — and must not fail a valid first page.
615	// After the reorg commits, that cursor must die with a zeroed
616	// ErrQueryChanged: the records the new times filter in may not be appended
617	// after the old page.
618	func TestQueryTxsTimeWindowFirstPageInFlightObservesCompleteOldTimes(t *testing.T) {
619		index := buildTwShiftOldChain(t)
620		h := installQueryReorgHooks(t, true, false, 5)
621		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
622	
623		result := make(chan TxPage, 1)
624		errCh := make(chan error, 1)
625		go func() {
626			page, err := index.QueryTxs(twShiftQuery())
627			if err != nil {
628				errCh <- err
629				return
630			}
631			result <- page
632		}()
633	
634		<-h.firstParked // first page holds index.mu and has pinned the old state
635		reorgDone := make(chan struct{})
636		go func() {
637			if _, err := index.Reorg(twShiftBranch()); err != nil {
638				errCh <- err
639			}
640			close(reorgDone)
641		}()
642	
643		close(h.releaseFirst) // the page scans and finishes against the old times
644		var got TxPage
645		select {
646		case got = <-result:
647		case err := <-errCh:
648			t.Fatalf("concurrent first page failed: %v", err)
649		}
650		want := twReferencePage(oldChain, twShiftPageSize, 0)
651		if err := classifyTimeWindowTxPage(got, want, twReferencePage(newChain, twShiftPageSize, 0),
652			twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd),
653			twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)); err != nil {
654			t.Fatalf("in-flight first page did not return one complete chain state:\n%v", err)
655		}
656		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
657			t.Fatalf("page holding the lock across reorg start must see the old times:\n%+v", got)
658		}
659		if !reflect.DeepEqual(got.Hits, literalTwShiftOldFirstPage().Hits) {
660			t.Fatalf("old first page hits=%v, want literal h1/h2 records", got.Hits)
661		}
662		if got.NextCursor == "" {
663			t.Fatal("old first page over 5 matches (page size 2) must carry a cursor")
664		}
665	
666		close(h.releaseReorg) // let the time-only reorg commit and return
667		<-reorgDone
668		if index.Tip != 5 {
669			t.Fatalf("tip after time-only reorg=%d, want 5", index.Tip)
670		}
671	
672		// The cursor pins the OLD timestamp state even though the height span,
673		// hashes, parent links and transaction lists are all unchanged: only the
674		// timestamp bytes in the fingerprint differ.
675		oldFingerprint := buildTwShiftOldChain(t)
676		payload := decodePayload(t, index, got.NextCursor)
677		if payload.To != 5 || payload.Off != 2 {
678			t.Fatalf("cursor pins to=%d off=%d, want 5/2", payload.To, payload.Off)
679		}
680		if payload.window() != (timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}) {
681			t.Fatalf("cursor window=%+v, want the pinned [0,110)", payload.window())
682		}
683		if payload.FP != fmt.Sprintf("%x", oldFingerprint.fingerprintLocked(1, 5)) {
684			t.Fatal("cursor fingerprint does not match the complete OLD timestamp state")
685		}
686	
687		// Continuing the old cursor on the new state must fail closed: no hits, no
688		// replacement cursor, no usable statistics — the h3/h4 records the new
689		// times filter in must never be stitched behind the h1/h2 old page.
690		page, err := index.QueryTxs(func() TxQuery {
691			q := twShiftQuery()
692			q.Cursor = got.NextCursor
693			return q
694		}())
695		if !errors.Is(err, ErrQueryChanged) {
696			t.Fatalf("old cursor across time-only reorg: err=%v page=%+v, want ErrQueryChanged", err, page)
697		}
698		if errors.Is(err, ErrInvalidArgument) {
699			t.Fatalf("a committed reorg must not be reported as an argument error: %v", err)
700		}
701		if !reflect.DeepEqual(page, TxPage{}) {
702			t.Fatalf("changed continuation must return a fully zeroed page, got %+v", page)
703		}
704	}
