706	// Ordering 2: the time-only reorg has fully committed (new timestamps live,
707	// Reorg still holding the lock) when the first page starts. It waits, then
708	// answers entirely against the NEW times — literal h1/h3 records, 5
709	// occurrences over 4 blocks, upper height 5 — and its cursor must drain the
710	// new state to the end with no duplicate or missing occurrence, identical
711	// statistics on every page, and no cursor once the last match is returned.
712	func TestQueryTxsTimeWindowFirstPageDuringCommittedReorgObservesCompleteNewTimes(t *testing.T) {
713		index := buildTwShiftOldChain(t)
714		h := installQueryReorgHooks(t, true, false, 5)
715		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
716	
717		reorgErr := make(chan error, 1)
718		go func() {
719			_, err := index.Reorg(twShiftBranch())
720			reorgErr <- err
721		}()
722		<-h.reorgParked // new timestamps applied (tip still 5), Reorg holds the lock
723	
724		result := make(chan TxPage, 1)
725		errCh := make(chan error, 1)
726		go func() {
727			page, err := index.QueryTxs(twShiftQuery())
728			if err != nil {
729				errCh <- err
730				return
731			}
732			result <- page
733		}()
734	
735		close(h.releaseReorg) // Reorg returns; the first lock the page can get is the new state
736		if err := <-reorgErr; err != nil {
737			t.Fatalf("time-only reorg failed: %v", err)
738		}
739		close(h.releaseFirst) // the parked first page can now scan and finish
740	
741		var got TxPage
742		select {
743		case got = <-result:
744		case err := <-errCh:
745			t.Fatalf("first page during committed reorg must not fail: %v", err)
746		}
747		want := twReferencePage(newChain, twShiftPageSize, 0)
748		if err := classifyTimeWindowTxPage(got, twReferencePage(oldChain, twShiftPageSize, 0), want,
749			twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd),
750			twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)); err != nil {
751			t.Fatalf("first page across reorg commit did not return one complete chain state:\n%v", err)
752		}
753		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
754			t.Fatalf("page after reorg commit must see the complete new times:\n%+v", got)
755		}
756		if !reflect.DeepEqual(got.Hits, literalTwShiftNewFirstPage().Hits) {
757			t.Fatalf("new first page hits=%v, want literal h1/h3 records", got.Hits)
758		}
759		if got.NextCursor == "" {
760			t.Fatal("new first page over 5 matches (page size 2) must carry a cursor")
761		}
762		for _, hit := range got.Hits {
763			if hit.Height == 2 {
764				t.Fatalf("old-time h2 occurrence must not appear under the new times: %+v", hit)
765			}
766		}
767	
