784		// exactly once, statistics fixed at 5/4/upper-5 on every page, and the
785		// cursor chain ends after the fifth occurrence.
786		query := twShiftQuery()
787		query.Cursor = got.NextCursor
788		all := append([]TxHit{}, got.Hits...)
789		pageCount := 1
790		for {
791			page, err := index.QueryTxs(query)
792			if err != nil {
