794			}
795			if page.TotalMatches != 5 || page.MatchedBlocks != 4 || page.ToHeight != 5 {
796				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageCount+1, page)
797			}
798			all = append(all, page.Hits...)
799			pageCount++
800			if page.NextCursor == "" {
801				break
802			}
803			query.Cursor = page.NextCursor
804		}
805		wantAll := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
806		if !reflect.DeepEqual(all, wantAll) {
807			t.Fatalf("new-state pagination duplicated or lost occurrences:\n got=%v\nwant=%v", all, wantAll)
808		}
809		if pageCount != 3 {
810			t.Fatalf("pages=%d, want 3 (2/2/1 over five hits)", pageCount)
811		}
812	}
