815	// timestamp state is untouched; once any pinned height is re-timed — even a
816	// block the window excluded (h3 at 110) or one with a missing timestamp (h4) —
817	// the continuation fails closed with a zeroed page. Repeating the exact old
818	// branch is a no-op-style reorg that leaves the cursor valid.
819	func TestQueryTxsTimeWindowCursorDiesOnAnyPinnedTimestampMove(t *testing.T) {
