889			}
890		})
891	}
892	
893	// Timing-independent overlap: reorgers alternate between the old and the new
894	// timestamp states while windowed readers paginate continuously, with no
895	// rendezvous hooks. The fixed tip and equal totals make this the dangerous
896	// case for a torn answer; every first page must classify as exactly one
897	// timestamp state, and every continuation must either keep draining that exact
898	// state or fail with a zeroed ErrQueryChanged.
899	func TestQueryTxsRepeatedTimeOnlyReorgsStayConsistent(t *testing.T) {
